export const RECOGNIZING_EMOTIONS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu emosi",q:"'Emosi' adalah...",options:["Perasaan yang muncul sebagai respons terhadap sesuatu yang kita alami, pikirkan, atau ingat","Reaksi tubuh yang hanya dialami orang dewasa dan tidak pernah muncul pada anak-anak","Tanda bahwa seseorang lemah atau sedang bermasalah dengan kepribadiannya sendiri"],answer:0,explain:"Emosi adalah bagian normal & penting dari menjadi manusia. Semua orang, di semua usia, merasakannya.",hint:"Perasaan yang muncul sebagai respons, atau tanda kelemahan?"},
{n:2,type:"mcq",micro:"Emosi dasar",q:"Beberapa emosi dasar yang dialami hampir semua orang:",options:["Emosi tidak bisa dikelompokkan atau dinamai","Senang, sedih, marah, takut, terkejut, jijik","Hanya senang & sedih, tidak ada yang lain"],answer:1,explain:"Ada banyak emosi, tapi beberapa 'dasar' ini muncul di berbagai budaya & mudah dikenali dari ekspresi wajah.",hint:"Beberapa emosi dasar, atau hanya senang & sedih?"},
{n:3,type:"mcq",micro:"Tidak ada emosi 'buruk'",q:"Sikap yang sehat terhadap emosi yang tidak menyenangkan (sedih, marah, takut):",options:["Emosi ini buruk & harus selalu ditekan atau disembunyikan, karena hanya akan merepotkan diri sendiri dan orang lain","Hanya emosi menyenangkan yang boleh dirasakan; perasaan lain berarti ada yang salah dengan kita","Emosi ini normal & bisa memberi informasi berguna; bukan 'buruk' & tidak perlu ditolak, meski tidak nyaman dirasakan"],answer:2,explain:"Semua emosi punya peran. Sedih bisa menandakan sesuatu yang berharga hilang; takut bisa melindungi kita dari bahaya. Yang penting cara kita meresponsnya.",hint:"Normal & memberi informasi, atau buruk & harus ditekan?"},
{n:4,type:"mcq",micro:"Emosi sebagai sinyal",q:"Emosi sering berfungsi seperti 'sinyal' yang memberi tahu kita...",options:["Ada sesuatu yang penting bagi kita sedang terjadi & mungkin butuh perhatian atau tindakan","Bahwa kita harus mengabaikan apa yang sedang terjadi & berpura-pura semuanya baik-baik saja saat itu juga","Tidak ada informasi apa pun, hanya gangguan yang sebaiknya dilawan sekuat tenaga supaya cepat hilang"],answer:0,explain:"Rasa cemas sebelum ujian bisa berarti 'ini penting bagiku'. Rasa marah bisa berarti 'ada yang terasa tidak adil'. Mendengarkan sinyalnya membantu memahami diri.",hint:"Memberi tahu ada hal penting terjadi, atau hanya gangguan?"},
{n:5,type:"mcq",micro:"Emosi & tubuh",q:"Emosi sering disertai perubahan di tubuh, seperti...",options:["Perubahan fisik hanya terjadi saat kita sedang sakit, bukan saat merasakan emosi","Jantung berdebar saat takut, dada terasa berat saat sedih, wajah panas saat marah","Tidak ada perubahan fisik saat beremosi, karena emosi hanya terjadi di dalam pikiran"],answer:1,explain:"Memperhatikan sensasi tubuh adalah salah satu cara mengenali emosi yang sedang kita rasakan, kadang tubuh 'tahu' sebelum pikiran menyadarinya.",hint:"Ada perubahan fisik yang menyertai, atau tidak ada sama sekali?"},
{n:6,type:"mcq",micro:"Memberi nama emosi",q:"Kenapa berguna memberi nama pada emosi yang sedang dirasakan ('aku merasa kecewa', bukan hanya 'aku merasa nggak enak')?",options:["Tidak ada gunanya, karena emosi tetap sama saja walaupun kita sudah menamainya dengan kata apa pun","Membuat emosi jadi lebih kuat & makin sulit dikendalikan setiap kali kita menyebutkan namanya","Menamai emosi dengan lebih tepat membantu kita memahaminya & sering membuatnya terasa sedikit lebih mudah dikelola"],answer:2,explain:"'Name it to tame it', memberi nama yang tepat pada perasaan sering membantu kita merasa sedikit lebih berjarak & sadar terhadapnya.",hint:"Membantu memahami & mengelola, atau tak berguna / memperkuat?"},
{n:7,type:"mcq",micro:"Beda perasaan & pikiran",q:"Manakah yang merupakan PERASAAN (emosi), bukan pikiran?",options:["'Cemas'","'Aku pasti akan gagal ujian besok'","'Sebaiknya aku belajar lebih giat'"],answer:0,explain:"Perasaan biasanya bisa disebut dengan satu kata (cemas, sedih, senang). Pikiran adalah kalimat/penilaian di kepala. Keduanya berbeda & saling memengaruhi.",hint:"Satu kata perasaan, atau kalimat penilaian di kepala?"},
{n:8,type:"mcq",micro:"Emosi datang & pergi",q:"Sifat emosi yang penting dipahami:",options:["Emosi hanya bisa dihilangkan dengan mengabaikannya; kalau diperhatikan, ia justru akan terus membesar","Emosi biasanya datang seperti gelombang, naik, memuncak, lalu mereda; jarang bertahan pada intensitas puncak selamanya","Emosi yang muncul akan bertahan selamanya pada kekuatan yang sama tanpa pernah berubah atau mereda"],answer:1,explain:"Menyadari bahwa emosi kuat biasanya akan mereda dengan sendirinya (bahkan tanpa kita melakukan apa pun) bisa membantu saat sedang merasa kewalahan.",hint:"Datang seperti gelombang lalu mereda, atau bertahan selamanya?"},
{n:9,type:"order",micro:"Langkah mengenali emosi",q:"Urutkan langkah sederhana untuk mengenali emosi yang sedang kamu rasakan.",items:["Berhenti sejenak & perhatikan bahwa ada 'sesuatu' yang kamu rasakan","Perhatikan sensasi di tubuh (dada, perut, wajah, bahu)","Coba beri nama pada perasaan itu (sedih? kesal? cemas? malu?)","Tanya diri: apa yang mungkin memicu perasaan ini?"],answer:[0,1,2,3],explain:"Berhenti → rasakan tubuh → beri nama → cari pemicunya. Ini bukan untuk menghilangkan emosi, tapi untuk memahaminya.",hint:"Memberi nama emosi dilakukan sebelum atau sesudah memperhatikan sensasi tubuh?"},
{n:10,type:"mcq",micro:"Mengenali bukan menghakimi",q:"Mengenali emosi berbeda dari menghakimi diri karena merasakannya:",options:["Keduanya sama saja","Menghakimi diri adalah cara terbaik mengelola emosi","Mengenali = 'oh, aku sedang merasa marah'; menghakimi = 'aku tidak seharusnya marah, aku payah'. Yang pertama membantu, yang kedua menambah beban"],answer:2,explain:"Menerima bahwa kita sedang merasakan sesuatu (tanpa langsung menghakimi diri) adalah langkah pertama yang sehat.",hint:"Mengamati tanpa menghakimi, atau menghakimi diri?"},
{n:11,type:"tf",micro:"Semua orang merasakan emosi",q:"Benar atau Salah: Setiap orang, tidak peduli usia, latar belakang, atau seberapa 'tenang' mereka terlihat dari luar, merasakan emosi.",answer:true,explain:"Orang mungkin mengekspresikan emosi secara berbeda, tapi merasakannya adalah bagian universal dari menjadi manusia.",hint:"Semua orang merasakannya, atau hanya sebagian orang?"},
{n:12,type:"tf",micro:"Menangis tanda lemah?",q:"Benar atau Salah: Menangis adalah tanda kelemahan yang harus selalu dihindari.",answer:false,explain:"Sebaliknya, menangis adalah respons alami tubuh terhadap emosi kuat (sedih, terharu, lega) & bisa membantu melepaskan ketegangan. Ini normal untuk siapa saja.",hint:"Tanda lemah, atau respons alami yang normal?"},
{n:13,type:"mcq",micro:"Emosi campuran",q:"Kadang kita bisa merasakan lebih dari satu emosi sekaligus, misalnya...",options:["Senang & sedih sekaligus saat perpisahan (senang karena kenangan indah, sedih karena berpisah)","Itu tidak mungkin, karena hanya satu emosi saja yang bisa dirasakan pada satu waktu oleh seseorang","Emosi campuran berarti ada yang salah dengan kita, sehingga perlu segera dipaksa memilih salah satu"],answer:0,explain:"Merasakan emosi campuran adalah hal yang normal & umum, terutama dalam situasi yang kompleks.",hint:"Bisa dirasakan bersamaan, atau hanya satu emosi pada satu waktu?"},
{n:14,type:"mcq",micro:"Intensitas emosi",q:"Emosi bisa dirasakan dalam berbagai tingkat kekuatan, misalnya dari...",options:["Hanya ada 'marah' atau 'tidak marah', tidak ada di antaranya","Sedikit kesal → cukup marah → sangat marah/murka","Emosi selalu dirasakan pada tingkat yang sama persis"],answer:1,explain:"Mengenali tingkat intensitas ('aku sedikit kesal' vs 'aku sangat marah') membantu kita merespons dengan lebih tepat.",hint:"Berbagai tingkat kekuatan, atau selalu sama / hanya ada/tidak?"},
{n:15,type:"mcq",micro:"Emosi & wajah",q:"Ekspresi wajah orang lain bisa memberi petunjuk tentang emosi mereka, tapi...",options:["Selalu 100% akurat menunjukkan perasaan sebenarnya, jadi kita tidak perlu bertanya apa pun lagi","Tidak ada hubungan antara wajah & emosi, sehingga ekspresi seseorang tidak bisa dijadikan petunjuk sama sekali","Tidak selalu akurat; kadang orang menyembunyikan atau salah membaca ekspresi, jadi bertanya langsung lebih pasti"],answer:2,explain:"Ekspresi wajah adalah petunjuk, bukan bukti pasti. Orang bisa 'tersenyum' padahal sedih. Bertanya dengan baik lebih membantu.",hint:"Petunjuk tapi tak selalu akurat, atau selalu akurat / tak berhubungan?"},
{n:16,type:"tf",micro:"Emosi bukan pilihan, respons adalah pilihan",q:"Benar atau Salah: Baik emosi yang muncul maupun cara kita meresponsnya sepenuhnya di luar kendali kita & tidak bisa dilatih.",answer:false,explain:"Sebaliknya, kita memang tidak selalu bisa memilih emosi yang muncul (sering otomatis), tapi kita bisa belajar & melatih bagaimana meresponsnya.",hint:"Respons bisa dilatih meski emosi muncul otomatis, atau keduanya sepenuhnya di luar kendali?"},
{n:17,type:"mcq",micro:"Menahan emosi terus-menerus",q:"Selalu menahan/menyembunyikan semua emosi tanpa pernah mengakuinya bisa...",options:["Membuat emosi menumpuk & terasa lebih berat; mengakui perasaan (setidaknya pada diri sendiri) biasanya lebih sehat","Jadi cara terbaik menghadapi emosi, karena perasaan yang tidak diakui akan hilang dengan sendirinya","Membuat emosi hilang tanpa efek, jadi kita tidak perlu mengakui perasaan kepada orang lain"],answer:0,explain:"Mengakui bahwa kita merasakan sesuatu (bukan berarti harus meledak) berbeda dari menekan & berpura-pura tidak merasakan apa-apa.",hint:"Bisa menumpuk & terasa berat, atau cara terbaik / hilang tanpa efek?"},
{n:18,type:"mcq",micro:"Emosi & pengambilan keputusan",q:"Saat sedang dalam emosi yang sangat kuat (sangat marah, sangat takut), keputusan yang dibuat...",options:["Tidak dipengaruhi emosi, sehingga kita bisa memutuskan hal penting sama baiknya setiap saat","Sering kurang bijak; sering lebih baik menunggu sampai lebih tenang sebelum memutuskan hal penting","Lebih baik karena dibuat 'dari hati', jadi sebaiknya langsung diputuskan saat emosi memuncak"],answer:1,explain:"Emosi kuat mempersempit cara berpikir kita. Memberi jeda ('aku akan putuskan nanti setelah tenang') sering menghasilkan keputusan yang lebih baik.",hint:"Sering kurang bijak saat emosi puncak, atau selalu lebih baik?"},
{n:19,type:"mcq",micro:"Belajar mengenali emosi",q:"Kemampuan mengenali & memberi nama emosi sendiri...",options:["Adalah bakat tetap sejak lahir yang tidak bisa dipelajari, jadi yang tidak pandai tidak akan pernah bisa","Tidak berguna untuk dipelajari, karena perasaan akan terasa sama saja dengan atau tanpa nama yang tepat","Bisa dilatih & berkembang seiring waktu, seperti keterampilan lain, tidak semua orang otomatis pandai sejak awal"],answer:2,explain:"Semakin sering kita berlatih memperhatikan & menamai perasaan, semakin mudah & alami prosesnya.",hint:"Bisa dilatih & berkembang, atau bakat tetap / tak berguna?"},
{n:20,type:"open",micro:"Catatan emosi sehari",q:"Selama satu hari, catat 3 momen berbeda ketika kamu merasakan emosi yang cukup jelas. Untuk masing-masing, tulis: (a) apa yang terjadi (pemicunya), (b) emosi apa yang kamu rasakan (coba beri nama setepat mungkin), (c) apa yang kamu rasakan di tubuh, (d) berapa lama emosi itu bertahan cukup kuat sebelum mereda.",explain:"Jawaban baik: 3 momen yang benar-benar berbeda, dengan pemicu yang spesifik, upaya menamai emosi setepat mungkin (bukan hanya 'senang'/'sedih'), kesadaran akan sensasi tubuh yang menyertai, & pengamatan bahwa emosi berubah/mereda seiring waktu.",hint:"Untuk (b), coba lebih spesifik dari kata dasar, mis. 'kecewa' bukan hanya 'sedih', 'lega' bukan hanya 'senang'.",sample:"Momen 1: (a) Aku dapat nilai bagus di ujian Matematika yang kupikir akan jelek. (b) Emosi: lega bercampur bangga & sedikit terkejut. (c) Di tubuh: dada terasa ringan, aku jadi ingin tersenyum & bercerita ke orang lain. (d) Bertahan cukup kuat sekitar 20 menit, lalu jadi rasa senang yang lebih tenang sepanjang hari. Momen 2: (a) Temanku membatalkan rencana main bersama di menit terakhir tanpa alasan jelas. (b) Emosi: kecewa & sedikit kesal, mungkin juga sedih. (c) Di tubuh: perut terasa mengganjal, bahu jadi tegang, aku jadi kurang berselera makan siang. (d) Cukup kuat sekitar 1 jam, lalu mereda saat aku mengalihkan diri dengan membaca. Momen 3: (a) Aku hampir terlambat masuk kelas karena ketinggalan angkot. (b) Emosi: panik & cemas. (c) Di tubuh: jantung berdebar kencang, napas jadi pendek, tangan agak berkeringat. (d) Sangat kuat sekitar 10 menit sampai aku sampai & duduk, lalu mereda cukup cepat setelah aku sadar tidak jadi terlambat."},
{n:21,type:"classify",micro:"Perasaan vs pikiran",q:"Kelompokkan tiap ungkapan ke 'Perasaan (emosi)' atau 'Pikiran (penilaian di kepala)'.",items:["Kesal","'Semua orang pasti menertawakanku'","Lega","'Aku harus segera meminta maaf'"],groups:["Perasaan (emosi)","Pikiran (penilaian di kepala)"],answer:{"Perasaan (emosi)":["Kesal","Lega"],"Pikiran (penilaian di kepala)":["'Semua orang pasti menertawakanku'","'Aku harus segera meminta maaf'"]},explain:"Perasaan: bisa disebut dengan satu kata. Pikiran: kalimat, penilaian, atau prediksi. Keduanya berbeda meski saling terkait.",hint:"Satu kata perasaan, atau kalimat penilaian/prediksi?"},
{n:22,type:"mcq",micro:"Kosakata emosi yang kaya",q:"Punya banyak kata untuk emosi (kecewa, cemas, jengkel, terharu, iri, malu, dll) membantu karena...",options:["Semakin tepat kita bisa menamai perasaan, semakin baik kita memahami apa yang sebenarnya kita butuhkan","Tidak ada manfaatnya, karena cukup memakai kata 'baik' atau 'buruk' untuk menjelaskan semua perasaan kita","Membuat kita jadi terlalu memikirkan perasaan sehingga malah lebih sulit memahami apa yang sedang terjadi"],answer:0,explain:"'Aku merasa iri' menuntun ke pemahaman & tindakan yang berbeda dari 'aku merasa marah', meski keduanya terasa tidak enak.",hint:"Membantu memahami kebutuhan, atau tak bermanfaat / berlebihan?"},
{n:23,type:"mcq",micro:"Emosi di bawah emosi",q:"Kadang di balik satu emosi ada emosi lain, misalnya di balik kemarahan bisa ada...",options:["Kebencian yang lebih besar terhadap orang yang membuat kita marah saat itu","Rasa takut, terluka, atau tidak dihargai yang lebih dalam & lebih rentan","Tidak ada apa-apa di baliknya, karena marah ya marah saja"],answer:1,explain:"Marah kadang 'menutupi' perasaan yang lebih rentan seperti terluka atau takut. Menyadari ini membantu memahami diri lebih dalam.",hint:"Bisa ada emosi lebih rentan di baliknya, atau tidak ada apa-apa?"},
{n:24,type:"mcq",micro:"Emosi & memori",q:"Kenapa mengingat kejadian tertentu bisa memunculkan emosi yang kuat lagi?",options:["Ingatan tidak pernah memengaruhi emosi, karena perasaan hanya dipengaruhi oleh hal yang terjadi saat ini","Emosi hanya muncul dari kejadian yang sedang berlangsung sekarang, bukan dari sesuatu yang sudah lewat","Ingatan bisa 'membawa kembali' perasaan yang menyertai kejadian aslinya, meski kejadiannya sudah lewat"],answer:2,explain:"Emosi terkait erat dengan ingatan. Ini kenapa cerita, lagu, atau tempat tertentu bisa membuat kita 'merasa lagi'.",hint:"Ingatan bisa membawa kembali perasaan, atau emosi hanya dari yang sedang terjadi?"},
{n:25,type:"mcq",micro:"Emosi yang tidak proporsional",q:"Kadang emosi terasa jauh lebih besar dari situasinya (mis. sangat marah karena hal sepele). Ini bisa berarti...",options:["Ada hal lain yang menumpuk (kelelahan, stres lain, perasaan yang belum selesai) yang membuat 'wadahnya' hampir penuh","Kita memang orang yang berlebihan & terlalu sensitif sehingga hal kecil pun terasa sangat besar bagi kita","Situasinya pasti sebenarnya sangat besar & serius, hanya saja kita tidak menyadarinya dengan jelas saat itu"],answer:0,explain:"Reaksi yang 'terlalu besar' sering jadi petunjuk untuk memeriksa: apa lagi yang sedang kutanggung? Emosi kecil bisa jadi 'tetes terakhir'.",hint:"Ada hal lain yang menumpuk, atau kita berlebihan / situasi memang besar?"},
{n:26,type:"mcq",micro:"Roda emosi",q:"'Roda emosi' adalah alat yang membantu...",options:["Menilai siapa yang emosinya paling kuat di antara teman-teman, lalu membandingkan mereka dengan satu sama lain","Menemukan kata yang lebih tepat untuk perasaan, dengan emosi dasar di tengah & variasi yang lebih spesifik di lingkaran luar","Meramal emosi apa yang akan kita rasakan besok, minggu depan, atau tahun depan secara pasti dan akurat"],answer:1,explain:"Roda emosi membantu bergerak dari 'aku merasa buruk' ke sesuatu yang lebih spesifik seperti 'aku merasa terabaikan' atau 'aku merasa cemburu'.",hint:"Menemukan kata yang lebih tepat, atau meramal / menilai?"},
{n:27,type:"tf",micro:"Emosi netral itu ada",q:"Benar atau Salah: Kita seharusnya selalu merasakan emosi yang intens; keadaan netral & tenang berarti ada yang salah dengan kita.",answer:false,explain:"Sebaliknya, kadang berada dalam keadaan cukup netral/tenang, tidak sangat senang maupun sangat sedih, adalah keadaan yang normal & baik. Tidak selalu harus merasakan emosi yang intens.",hint:"Keadaan netral itu normal, atau harus selalu merasakan emosi intens?"},
{n:28,type:"tf",micro:"Menekan emosi menghilangkannya?",q:"Benar atau Salah: Berusaha keras 'tidak merasakan' sebuah emosi & menekannya sepenuhnya biasanya membuat emosi itu hilang total tanpa efek apa pun.",answer:false,explain:"Sebaliknya, menekan emosi sering hanya menyembunyikannya sementara; ia bisa muncul kembali dengan cara lain (mudah lelah, tegang, meledak tak terduga). Mengakui perasaan lebih sehat daripada menekannya terus-menerus.",hint:"Menghilangkannya total, atau hanya menyembunyikannya sementara?"},
{n:29,type:"mcq",micro:"Emosi & pikiran saling memengaruhi",q:"Hubungan antara pikiran & emosi:",options:["Sepenuhnya terpisah & tidak saling memengaruhi, jadi apa yang dipikirkan tidak berpengaruh pada perasaan kita","Hanya emosi yang memengaruhi pikiran kita, sedangkan pikiran tidak bisa memengaruhi emosi","Saling memengaruhi, pikiran ('aku akan gagal') bisa memunculkan emosi (cemas), & emosi (cemas) bisa membuat pikiran makin negatif"],answer:2,explain:"Menyadari lingkaran ini membantu: kadang menenangkan pikiran meredakan emosi, & kadang menenangkan tubuh/emosi membuat pikiran lebih jernih.",hint:"Saling memengaruhi dua arah, atau terpisah / satu arah?"},
{n:30,type:"order",micro:"Menemukan nama emosi yang lebih tepat",q:"Urutkan langkah bergerak dari 'aku merasa nggak enak' ke perasaan yang lebih spesifik.",items:["Akui dulu: 'aku merasa nggak enak/tidak nyaman'","Perhatikan apakah lebih ke arah sedih, marah, takut, atau malu","Perkecil lagi: kalau sedih, apakah lebih ke kecewa, kesepian, atau kehilangan?","Cek: apakah nama itu terasa 'pas' saat kamu mengucapkannya dalam hati?"],answer:[0,1,2,3],explain:"Akui yang umum → arahkan ke kelompok emosi → perkecil ke yang lebih spesifik → cek apakah terasa pas. Ini proses menyaring, bukan tebak-tebakan.",hint:"Mengecek apakah nama emosi terasa 'pas' dilakukan di awal atau di akhir?"},
{n:31,type:"mcq",micro:"Emosi yang sama, ekspresi berbeda",q:"Dua orang bisa merasakan emosi yang sama (mis. gugup) tapi menunjukkannya berbeda karena...",options:["Kepribadian, kebiasaan, & budaya memengaruhi cara orang mengekspresikan perasaan (ada yang jadi diam, ada yang jadi banyak bicara)","Salah satu dari mereka berbohong tentang perasaannya, karena emosi yang sama tampak sama di mata orang yang melihat","Emosi yang sama ditunjukkan dengan cara yang sama oleh orang di mana pun, tanpa ada perbedaan"],answer:0,explain:"Tidak bisa selalu menilai perasaan seseorang dari luar. Ada yang menyembunyikan kegugupan dengan tertawa, ada yang jadi pendiam.",hint:"Ekspresi bisa berbeda-beda, atau selalu sama / salah satu bohong?"},
{n:32,type:"tf",micro:"Emosi memberi info tentang nilai kita",q:"Benar atau Salah: Emosi yang kita rasakan tidak memberi informasi apa pun tentang nilai-nilai atau apa yang kita pedulikan.",answer:false,explain:"Sebaliknya, emosi sering mengungkap apa yang kita pedulikan, kita marah karena keadilan penting bagi kita, sedih karena sesuatu yang kita hargai hilang. Mendengarkannya membantu mengenali nilai & kebutuhan diri.",hint:"Mengungkap apa yang kita pedulikan, atau tak memberi info apa pun?"},
{n:33,type:"mcq",micro:"Membedakan emosi & kebutuhan",q:"Di balik emosi biasanya ada kebutuhan, misalnya di balik rasa kesepian ada kebutuhan akan...",options:["Lebih banyak waktu sendirian","Koneksi/kebersamaan dengan orang lain","Tidak ada apa-apa"],answer:1,explain:"Menerjemahkan emosi jadi kebutuhan ('aku kesepian' → 'aku butuh terhubung dengan seseorang') membuat lebih jelas apa yang bisa membantu.",hint:"Kebutuhan akan koneksi, atau tak ada apa-apa / lebih menyendiri?"},
{n:34,type:"mcq",micro:"Emosi orang lain bukan tanggung jawab penuh kita",q:"Kalau seseorang di sekitarmu sedang beremosi kuat, penting diingat...",options:["Kamu wajib membuat perasaan orang lain jadi baik, & kalau gagal berarti itu sepenuhnya kesalahanmu sendiri","Emosi orang lain bukan urusanmu, jadi kamu tidak perlu peduli pada apa yang mereka rasakan","Kamu bisa peduli & membantu sebisamu, tapi kamu tidak sepenuhnya bertanggung jawab 'memperbaiki' perasaan orang lain"],answer:2,explain:"Empati itu baik, tapi menanggung sepenuhnya perasaan semua orang di sekitar bisa melelahkan & tidak realistis. Keseimbangan itu penting.",hint:"Peduli & bantu sebisanya tanpa menanggung sepenuhnya, atau selalu wajib / tak peduli?"},
{n:35,type:"mcq",micro:"Emosi berulang sebagai pola",q:"Kalau kamu sering merasakan emosi yang sama di situasi tertentu (mis. selalu cemas sebelum presentasi), itu...",options:["Pola yang berguna dikenali; menyadarinya membantu bersiap & memahami diri lebih baik","Berarti ada yang salah dengan dirimu, sehingga kamu harus berusaha menghilangkan perasaan itu","Sesuatu yang harus diabaikan, karena memperhatikan pola membuatmu makin cemas"],answer:0,explain:"Mengenali pola emosi pribadi ('aku cenderung mudah kesal saat lapar') membantu kita mengantisipasi & merawat diri lebih baik.",hint:"Pola berguna dikenali, atau ada yang salah besar / harus diabaikan?"},
{n:36,type:"mcq",micro:"Rasa iri & cemburu",q:"Merasa iri saat melihat pencapaian orang lain adalah...",options:["Sesuatu yang tidak dirasakan orang baik, jadi kalau merasakannya kita sebaiknya menyembunyikannya rapat dari orang lain","Emosi manusiawi yang normal; yang penting bagaimana kita meresponsnya (belajar dari mereka, atau membiarkannya jadi kebencian)","Tanda bahwa kita orang jahat yang tidak bisa ikut senang melihat keberhasilan orang lain"],answer:1,explain:"Iri adalah perasaan yang hampir semua orang alami. Ia bisa jadi petunjuk tentang apa yang kita inginkan, & cara kita menanggapinya adalah pilihan kita.",hint:"Normal & soal respons, atau tanda orang jahat?"},
{n:37,type:"tf",micro:"Emosi tidak selalu 'akurat'",q:"Benar atau Salah: Emosi selalu 'benar' tentang kenyataan; kalau kita merasa terancam, berarti kita pasti sedang dalam bahaya.",answer:false,explain:"Sebaliknya, emosi adalah data berharga tapi bukan fakta absolut. Kita bisa merasa terancam padahal aman, atau merasa bersalah padahal tidak salah, jadi berguna memeriksa 'apakah perasaan ini sesuai kenyataan?'",hint:"Tidak selalu akurat & bisa diperiksa, atau selalu benar tentang kenyataan?"},
{n:38,type:"mcq",micro:"Menghormati emosi tanpa dikuasai olehnya",q:"Sikap yang seimbang terhadap emosi kuat:",options:["Bertindak sesuai dorongan emosi saat itu juga, tanpa berpikir panjang atau menunggu dulu","Sepenuhnya mengabaikan emosi & tidak mendengarkan pesannya, supaya keputusan tak terpengaruh perasaan","Akui & dengarkan pesannya, tapi tidak langsung bertindak berdasarkan setiap dorongan yang muncul dari emosi itu"],answer:2,explain:"'Aku merasa sangat marah & ingin membalas' bisa diakui, sambil memilih untuk tidak langsung membalas. Mengenali emosi tidak berarti dikuasai olehnya.",hint:"Akui tapi tidak langsung bertindak dari setiap dorongan, atau selalu bertindak / abaikan total?"},
{n:39,type:"mcq",micro:"Emosi & seni/cerita",q:"Kenapa film, lagu, & buku bisa membuat kita merasakan emosi yang kuat?",options:["Kisah & musik bisa menggerakkan bagian emosional otak seperti pengalaman nyata, & ini bisa jadi cara aman mengenali & memahami perasaan","Itu berarti kita terlalu sensitif & lemah, karena orang yang kuat tidak akan tersentuh oleh cerita atau musik apa pun","Tidak ada hubungan antara seni & emosi, jadi perasaan yang muncul saat itu hanyalah kebetulan yang tidak berarti"],answer:0,explain:"Merasakan emosi lewat cerita bisa membantu kita 'melatih' mengenali & memahami perasaan dalam konteks yang aman.",hint:"Cara aman mengenali perasaan, atau tanda terlalu sensitif?"},
{n:40,type:"open",micro:"Membongkar sebuah emosi",q:"Pilih satu emosi kuat yang pernah kamu rasakan baru-baru ini. Analisis: (a) beri nama emosi itu setepat mungkin, (b) apakah ada emosi lain 'di baliknya' yang lebih rentan (mis. di balik marah ada terluka), (c) apa kebutuhan yang mungkin ada di balik perasaan itu, (d) apa yang emosi itu dorong kamu untuk lakukan, & apakah kamu memilih mengikutinya atau tidak.",explain:"Jawaban baik: nama emosi yang spesifik, kesadaran akan emosi yang lebih rentan di baliknya (bukan hanya emosi permukaan), identifikasi kebutuhan yang masuk akal, & refleksi jujur tentang dorongan emosi vs pilihan yang diambil (menunjukkan bahwa mengenali emosi tidak berarti dikuasai olehnya).",hint:"Bagian (b) sering terlewat, banyak emosi 'permukaan' seperti marah menutupi perasaan yang lebih rentan seperti takut, malu, atau terluka.",sample:"(a) Emosi: aku merasa sangat kesal & marah saat kelompok tugasku terus-menerus mengabaikan ide-ideku dalam diskusi. (b) Emosi di baliknya: kalau kupikirkan lebih dalam, di balik marah itu ada rasa tidak dihargai & sedikit terluka, seolah aku tidak dianggap penting di kelompok itu. (c) Kebutuhan di baliknya: aku butuh merasa didengar & dianggap punya kontribusi yang berarti, bukan hanya 'ada' di kelompok. (d) Dorongan emosi & pilihanku: emosi itu mendorongku untuk diam saja & tidak mau ikut berkontribusi lagi sebagai 'balasan', atau membalas dengan nada tajam. Aku memilih untuk tidak langsung mengikuti dorongan itu. Setelah agak tenang, aku memutuskan untuk menyampaikan dengan tenang di pertemuan berikutnya, 'Aku merasa beberapa idenya belum sempat dibahas, boleh kita luangkan waktu mendengar dari semua orang bergiliran?' supaya kebutuhanku terpenuhi tanpa merusak kerja sama."},
{n:41,type:"mcq",micro:"Cek diri (check-in)",q:"'Cek diri' emosi yang sederhana bisa dilakukan dengan bertanya beberapa kali sehari:",options:["'Kenapa aku bermasalah & berbeda dari semua orang di sekitarku? Apa yang salah denganku?'","'Bagaimana perasaanku sekarang? Apa yang kurasakan di tubuhku? Apa yang mungkin memicunya?'","'Apa yang harus kulakukan agar mulai sekarang aku tidak merasakan apa-apa lagi?'"],answer:1,explain:"Cek diri singkat membangun kebiasaan sadar terhadap keadaan emosi, sehingga kita tidak kaget saat emosi tiba-tiba terasa besar.",hint:"Pertanyaan yang membantu menyadari perasaan, atau pertanyaan menghakimi diri?"},
{n:42,type:"mcq",micro:"Jurnal emosi",q:"Menulis jurnal tentang perasaan (mis. beberapa kalimat di akhir hari) bisa membantu karena...",options:["Membuat perasaan jadi lebih buruk, karena setiap kali ditulis kita justru makin tenggelam dalam hal-hal yang menyakitkan","Tidak ada gunanya sama sekali, karena menulis tidak mengubah apa pun dan perasaan tetap sama membingungkannya seperti sebelumnya","Menuliskan perasaan sering membuatnya terasa lebih jelas & lebih mudah dipahami dibanding hanya dipikirkan"],answer:2,explain:"Menulis 'memindahkan' perasaan dari kepala ke kertas, memberi jarak & kejelasan. Tidak perlu rapi atau panjang.",hint:"Membuat perasaan lebih jelas, atau lebih buruk / tak berguna?"},
{n:43,type:"mcq",micro:"Body scan sederhana",q:"'Pemindaian tubuh' (body scan) untuk mengenali emosi berarti...",options:["Memperhatikan sensasi di berbagai bagian tubuh (kepala, dada, perut, bahu, tangan) untuk melihat di mana ketegangan atau sensasi terkumpul","Memeriksa tubuh ke dokter secara rutin untuk mencari tahu penyakit apa saja yang mungkin sedang kita derita saat ini","Menghitung detak jantung terus-menerus sepanjang hari supaya kita tahu persis kapan jantung berdetak lebih cepat dari biasanya"],answer:0,explain:"Emosi sering 'tersimpan' di tubuh. Menyadari 'dadaku terasa berat' atau 'bahuku tegang' bisa jadi pintu masuk mengenali perasaan.",hint:"Memperhatikan sensasi di berbagai bagian tubuh, atau periksa ke dokter?"},
{n:44,type:"mcq",micro:"Skala 1-10",q:"Memberi angka pada intensitas emosi (mis. 'kekesalanku sekarang di angka 6 dari 10') membantu karena...",options:["Tidak berarti apa-apa, karena angka tidak bisa menggambarkan perasaan & hanya membuat kita bingung memikirkannya","Membuat perasaan lebih konkret & memudahkan melihat perubahannya seiring waktu ('tadi 8, sekarang 4')","Membuat perasaan jadi lebih rumit & lebih sulit dipahami, sebab kita malah sibuk memikirkan angka yang tepat"],answer:1,explain:"Skala angka mengubah perasaan yang kabur jadi sesuatu yang bisa 'dilacak', membantu menyadari bahwa emosi memang naik-turun.",hint:"Membuat lebih konkret & bisa dilacak, atau lebih rumit / tak berarti?"},
{n:45,type:"tf",micro:"Menamai emosi orang lain dengan hormat",q:"Benar atau Salah: Saat menebak perasaan orang lain, lebih baik memaksakan penilaian kita ('kamu pasti marah!') daripada menyampaikannya sebagai tebakan yang bisa dikoreksi.",answer:false,explain:"Sebaliknya, menyampaikan sebagai tebakan ('kamu kelihatan sedih, benar nggak?') menghormati bahwa kita tidak sepenuhnya tahu isi hati orang lain & memberi mereka ruang untuk mengoreksi atau menjelaskan.",hint:"Sampaikan sebagai tebakan yang bisa dikoreksi, atau paksakan penilaian kita?"},
{n:46,type:"mcq",micro:"Memberi ruang untuk emosi",q:"Kalau kamu merasakan emosi kuat & tidak sedang harus melakukan hal penting, salah satu respons yang sehat:",options:["Selalu langsung mengalihkan diri dengan kesibukan lain agar tidak merasakan apa pun, setiap kali perasaan itu muncul","Menyalahkan diri sendiri karena merasakannya, lalu memarahi diri sampai perasaan itu hilang dengan sendirinya sepenuhnya","Beri diri sedikit ruang & waktu untuk merasakannya (mis. duduk sebentar, menarik napas), alih-alih langsung mengalihkannya sepenuhnya"],answer:2,explain:"Memberi ruang bukan berarti berkubang dalam emosi selamanya, tapi mengizinkan diri merasakannya sejenak sebelum memutuskan langkah berikutnya.",hint:"Beri sedikit ruang untuk merasakan, atau selalu alihkan / salahkan diri?"},
{n:47,type:"mcq",micro:"Membedakan 'aku merasa' & 'aku adalah'",q:"Mengatakan 'aku sedang merasa cemas' berbeda dari 'aku adalah orang yang cemas' karena...",options:["'Merasa' menggambarkan keadaan sementara; 'adalah' menjadikannya identitas permanen, yang terasa lebih berat & sulit diubah","Keduanya sama saja","'Aku adalah' selalu lebih akurat"],answer:0,explain:"Bahasa yang kita pakai memengaruhi cara kita memandang emosi. 'Sedang merasa' mengakui bahwa perasaan datang & pergi.",hint:"'Merasa' = sementara, 'adalah' = identitas permanen, atau sama saja?"},
{n:48,type:"mcq",micro:"Mengenali pemicu pribadi",q:"Membuat daftar 'hal-hal yang biasanya memicu emosi kuat bagiku' (mis. dikritik di depan umum, merasa dikecualikan) membantu karena...",options:["Tidak berguna, karena pemicu emosi tidak bisa diketahui dan datang secara acak","Kamu bisa mengantisipasi & bersiap secara emosi saat situasi itu mungkin terjadi","Membuatmu terlalu waspada terus sampai tidak berani melakukan apa-apa dan menghindari orang"],answer:1,explain:"Mengenali pemicu pribadi bukan untuk menghindarinya selamanya, tapi untuk tidak selalu terkejut & lebih siap meresponsnya.",hint:"Membantu antisipasi & bersiap, atau membuat terlalu waspada / tak berguna?"},
{n:49,type:"mcq",micro:"Emosi saat lelah/lapar",q:"Menyadari bahwa kondisi fisik (lelah, lapar, kurang tidur) memengaruhi emosi membantu kita...",options:["Menganggap emosi tidak berhubungan dengan tubuh, sehingga rasa lelah & lapar tak perlu dipertimbangkan","Menyalahkan tubuh atas semua perasaan, sehingga tak perlu mencari tahu yang terjadi","Tidak buru-buru menyimpulkan 'aku benci semuanya' saat sebenarnya kita hanya sangat lelah & lapar"],answer:2,explain:"Kadang 'solusi' untuk emosi yang tiba-tiba buruk adalah makan, minum air, atau tidur, bukan menganalisis perasaan berjam-jam.",hint:"Membantu tidak buru-buru menyimpulkan, atau tak berhubungan / selalu salahkan tubuh?"},
{n:50,type:"order",micro:"Cek diri emosi yang lengkap",q:"Urutkan langkah cek diri emosi yang lengkap.",items:["Berhenti sejenak & sadari bahwa kamu sedang memeriksa perasaanmu","Perhatikan sensasi tubuh & beri nama pada emosi yang terasa","Perkirakan intensitasnya (mis. 1-10) & apa pemicunya","Tanya: apa yang kubutuhkan sekarang? (istirahat? bicara dengan seseorang? bergerak?)"],answer:[0,1,2,3],explain:"Berhenti → rasakan & namai → nilai intensitas & pemicu → tanyakan kebutuhan. Berakhir pada 'apa yang kubutuhkan', bukan sekadar pengamatan.",hint:"Menanyakan 'apa yang kubutuhkan' dilakukan di awal atau di akhir cek diri?"},
{n:51,type:"mcq",micro:"Berbagi perasaan dengan orang tepercaya",q:"Menceritakan perasaan ke orang yang kamu percaya (teman, keluarga) bisa membantu karena...",options:["Berbicara membuat perasaan lebih jelas, & merasa didengar sering mengurangi beratnya","Membebani orang lain & sebaiknya dihindari, karena orang lain sudah punya banyak masalah","Membuat perasaan menyebar & jadi lebih buruk daripada dipendam sendiri"],answer:0,explain:"Kita tidak harus menghadapi semua perasaan sendirian. Berbagi dengan orang yang tepat adalah cara sehat mengelola emosi.",hint:"Membuat lebih jelas & terasa lebih ringan, atau membebani / memperburuk?"},
{n:52,type:"tf",micro:"Latihan membuat lebih peka pada diri",q:"Benar atau Salah: Kemampuan mengenali & menamai emosi sendiri adalah bakat tetap; latihan tidak membuat seseorang lebih cepat mengenali perasaannya.",answer:false,explain:"Sebaliknya, seperti keterampilan lain, kesadaran emosi tumbuh dengan latihan. Awalnya mungkin terasa asing, lama-lama jadi lebih cepat & alami.",hint:"Meningkat dengan latihan, atau tetap sama?"},
{n:53,type:"mcq",micro:"Emosi & aktivitas menenangkan",q:"Saat mengenali emosi kuat, aktivitas sederhana yang bisa membantu menciptakan ruang untuk memahaminya:",options:["Berteriak sekencang-kencangnya pada orang di sekitar supaya semua kemarahan keluar sekaligus dan kita langsung merasa tenang","Menarik napas perlahan beberapa kali, berjalan sebentar, atau minum air, membantu tubuh sedikit lebih tenang sehingga pikiran lebih jernih","Menahan napas selama mungkin sampai wajah memerah supaya perasaan yang kuat itu terdorong keluar dari tubuh kita"],answer:1,explain:"Menenangkan tubuh sedikit (napas, gerak ringan) sering membuat kita lebih bisa memikirkan perasaan dengan jernih, bukan hanya terbawa arusnya.",hint:"Napas perlahan / gerak ringan / minum air, atau menahan napas / berteriak?"},
{n:54,type:"mcq",micro:"Mengenali emosi sebelum bereaksi",q:"Jeda singkat untuk mengenali emosi ('oh, aku sedang sangat kesal') SEBELUM bereaksi berguna karena...",options:["Membuat kita terlalu lambat merespons, sehingga sering ketinggalan dan kehilangan kesempatan penting","Tidak berpengaruh pada cara kita bertindak, karena tindakan kita sama saja dengan atau tanpa jeda itu","Memberi sedikit jarak antara perasaan & tindakan, sehingga kita lebih mungkin memilih respons yang tidak disesali"],answer:2,explain:"Jarak kecil ini, kadang hanya beberapa detik, sering cukup untuk mengubah reaksi impulsif menjadi respons yang lebih dipilih.",hint:"Memberi jarak antara perasaan & tindakan, atau membuat terlalu lambat / tak berpengaruh?"},
{n:55,type:"mcq",micro:"Mengenali emosi positif juga",q:"Sengaja memperhatikan & menikmati emosi menyenangkan (senang, bangga, tenang, terharu) saat muncul berguna karena...",options:["Membantu kita lebih menghargai momen baik & 'menyimpan' pengalaman positif, tidak hanya fokus pada yang sulit","Tidak penting, karena hanya emosi sulit yang perlu dikenali & diperhatikan, sedangkan emosi menyenangkan akan datang sendiri","Membuat kita jadi terlalu senang secara berlebihan sampai lupa pada tanggung jawab dan masalah yang sebenarnya penting"],answer:0,explain:"Mengenali emosi tidak hanya soal menangani yang sulit; menyadari & menikmati yang baik juga bagian penting dari kesejahteraan.",hint:"Membantu menghargai momen baik, atau tak penting / berlebihan?"},
{n:56,type:"tf",micro:"Tidak semua perlu 'diperbaiki'",q:"Benar atau Salah: Setiap emosi yang tidak menyenangkan harus segera dicari cara 'memperbaiki' atau menghilangkannya; membiarkan diri merasakannya berarti membiarkan diri terpuruk.",answer:false,explain:"Sebaliknya, kadang mengenali emosi cukup dengan 'oh, aku sedang sedih hari ini' tanpa langsung buru-buru mengubahnya. Mengizinkan diri merasakan sesuatu tanpa panik adalah bagian dari hubungan yang sehat dengan emosi.",hint:"Cukup diakui tanpa harus langsung diperbaiki, atau setiap emosi harus segera dihilangkan?"},
{n:57,type:"mcq",micro:"Emosi & waktu yang tepat",q:"Kalau kamu menyadari sedang beremosi kuat saat harus melakukan hal penting (ujian, presentasi), yang bisa membantu:",options:["Membatalkan tugas penting itu sampai perasaannya hilang sepenuhnya, baru kemudian dilakukan lagi pada kesempatan lain, walaupun tenggat waktunya sudah lewat","Akui perasaannya secara singkat ('aku gugup, itu wajar'), lakukan hal menenangkan sebentar, lalu fokus pada tugas; proses lebih dalam bisa dilakukan nanti","Memaksa diri 'tidak merasakan apa-apa' sampai selesai, lalu menganggap perasaan itu tidak pernah ada sebelumnya, sehingga tidak perlu dibicarakan kepada siapa pun"],answer:1,explain:"Kita bisa mengakui perasaan tanpa harus menyelesaikannya saat itu juga. 'Nanti aku pikirkan lebih dalam' adalah pilihan yang sah.",hint:"Akui singkat + tenangkan + fokus, atau paksa tak merasa / batalkan?"},
{n:58,type:"mcq",micro:"Mengenali emosi dalam kelompok",q:"Dalam kelompok/kelas, menyadari 'suasana emosi' bersama (semua tegang sebelum ujian, semua bersemangat sebelum acara) membantu karena...",options:["Tidak ada gunanya memperhatikan suasana kelompok, karena yang penting hanya perasaan kita sendiri","Suasana kelompok tidak memengaruhi individu, jadi perilaku orang tak terkait perasaan","Kita jadi lebih paham perilaku orang di sekitar & bisa lebih peka dalam berinteraksi"],answer:2,explain:"Emosi bisa 'menular' dalam kelompok. Menyadari ini membantu kita tidak bingung ('kenapa semua jadi sensitif hari ini?') & lebih bijak merespons.",hint:"Membantu lebih paham & peka, atau tak berguna / tak berpengaruh?"},
{n:59,type:"mcq",micro:"Kesabaran pada proses",q:"Kalau kamu masih kesulitan menamai emosi dengan tepat, sikap yang membantu:",options:["Tidak apa-apa, ini keterampilan yang butuh latihan; teruskan mencoba tanpa menuntut kesempurnaan","Menyerah saja karena 'aku memang tidak peka', sebab kemampuan ini tidak bisa dipelajari orang tak berbakat","Menghakimi diri karena tidak langsung bisa, & terus mengkritik diri sampai akhirnya mampu"],answer:0,explain:"Mengenali emosi dengan tepat bisa terasa sulit di awal, terutama kalau tidak terbiasa. Itu wajar & akan membaik dengan latihan.",hint:"Butuh latihan & wajar, atau menyerah / menghakimi diri?"},
{n:60,type:"open",micro:"Rancang kebiasaan cek diri emosi",q:"Rancang kebiasaan 'cek diri emosi' untuk kamu praktikkan selama 2 minggu. Sertakan: (a) kapan & seberapa sering kamu akan melakukannya, (b) 3-4 pertanyaan yang akan kamu tanyakan pada diri sendiri, (c) bagaimana kamu akan mencatat/mengingatnya (jurnal, aplikasi, catatan singkat), (d) satu hal yang kamu harap bisa lebih kamu pahami tentang dirimu setelah 2 minggu.",explain:"Jawaban baik: jadwal cek diri yang realistis (bukan 'setiap saat'), 3-4 pertanyaan yang benar-benar membantu menyadari perasaan (menamai, sensasi tubuh, intensitas & pemicu, kebutuhan), cara mencatat yang praktis & bisa dijalankan, & harapan pemahaman yang spesifik (bukan generik 'ingin lebih mengenal diri').",hint:"Pertanyaan (b) sebaiknya mencakup: menamai emosi, sensasi tubuh, intensitas/pemicu, & kebutuhan, empat sudut yang berbeda.",sample:"(a) Kapan & seberapa sering: aku akan cek diri 2 kali sehari, satu kali sepulang sekolah (saat ganti suasana) & satu kali sebelum tidur, masing-masing sekitar 2-3 menit. (b) Pertanyaan yang kutanyakan: (1) 'Apa yang paling kuat kurasakan sekarang, & bisakah kuberi nama yang lebih tepat dari sekadar baik/buruk?' (2) 'Di mana di tubuhku aku merasakan sesuatu, & seperti apa rasanya?' (3) 'Dari 1 sampai 10, seberapa kuat perasaan ini, & apa yang mungkin memicunya hari ini?' (4) 'Apa yang aku butuhkan sekarang, istirahat, bicara dengan seseorang, bergerak, atau hanya membiarkan diri merasakan sebentar?' (c) Cara mencatat: aku akan menyimpan buku catatan kecil di tas & di meja belajar, & menulis 3-4 baris singkat tiap cek diri (tidak perlu rapi), plus satu kata emosi utama hari itu di bagian atas halaman supaya mudah dilihat polanya nanti. (d) Yang kuharap lebih kupahami: aku ingin tahu apakah ada situasi atau waktu tertentu yang berulang membuat emosiku turun (mungkin hari-hari tertentu, atau setelah kegiatan tertentu), supaya aku bisa lebih siap & merawat diri lebih baik di saat-saat itu."},
{n:61,type:"mcq",micro:"Emosi kita vs emosi kita 'tertular'",q:"Kadang kita jadi ikut sedih/cemas karena berada dekat orang yang sedang sedih/cemas. Menyadari ini membantu kita...",options:["Menghindari semua orang yang sedang beremosi supaya perasaan mereka tidak menular kepada kita, termasuk keluarga dan teman dekat","Membedakan 'ini perasaanku sendiri' dari 'ini perasaan yang kutangkap dari orang lain', sehingga bisa merespons dengan lebih tepat","Menganggap kita tidak boleh merasakan apa-apa di dekat orang lain, karena perasaan harus disembunyikan"],answer:1,explain:"Empati bisa membuat kita 'menyerap' emosi orang lain. Menyadari asal-usulnya membantu kita menjaga keseimbangan sambil tetap peduli.",hint:"Membedakan asal emosi, atau tak boleh merasa / menghindari semua orang?"},
{n:62,type:"mcq",micro:"Emosi & budaya",q:"Cara mengekspresikan emosi (menangis di depan umum, menunjukkan kemarahan, menampilkan kegembiraan) bisa berbeda antar budaya & keluarga. Ini artinya...",options:["Satu budaya lebih benar dari yang lain, sehingga setiap orang sebaiknya mengikuti cara yang sama di mana pun","Emosi sebaiknya tidak ditunjukkan di depan orang lain, karena menunjukkan perasaan memalukan","Tidak ada satu cara 'benar' mengekspresikan emosi; yang penting perasaannya diakui, cara menunjukkannya bisa beragam"],answer:2,explain:"Memahami keberagaman ekspresi emosi mencegah kita menghakimi orang lain 'terlalu berlebihan' atau 'terlalu dingin' hanya karena berbeda dari kebiasaan kita.",hint:"Beragam & tak ada yang paling benar, atau satu budaya paling benar / tak boleh ditunjukkan?"},
{n:63,type:"mcq",micro:"Ketika mengenali emosi terasa menyakitkan",q:"Kadang mengenali & mengakui emosi tertentu (kesedihan mendalam, kehilangan) terasa menyakitkan. Sikap yang sehat:",options:["Boleh melakukannya perlahan & dengan dukungan; tidak harus menghadapi semuanya sekaligus sendirian","Harus langsung menghadapi semua perasaan sekaligus tanpa bantuan, sebab hanya cara itu yang berhasil","Sebaiknya tidak mengakui emosi yang menyakitkan, karena mengakuinya membuat luka makin dalam"],answer:0,explain:"Untuk perasaan yang berat, mengenalinya secara bertahap & dengan dukungan orang tepercaya (atau bantuan profesional bila perlu) lebih sehat daripada memaksakan diri sendirian.",hint:"Perlahan & dengan dukungan, atau langsung sendirian / tak pernah?"},
{n:64,type:"tf",micro:"Meminta bantuan untuk emosi yang berat",q:"Benar atau Salah: Kalau ada perasaan yang terasa sangat berat, berlangsung lama, & mengganggu kegiatan sehari-hari (tidur, sekolah, makan, hubungan), bicara dengan orang dewasa tepercaya atau mencari bantuan profesional adalah langkah bijak.",answer:true,explain:"Sama seperti tubuh yang sakit butuh perhatian, perasaan yang berat & berkepanjangan juga layak mendapat dukungan. Meminta bantuan adalah kekuatan, bukan kelemahan.",hint:"Bijak mencari bantuan, atau harus ditangani sendiri selalu?"},
{n:65,type:"mcq",micro:"Emosi yang 'mati rasa'",q:"Kadang seseorang merasa 'tidak merasakan apa-apa' atau kosong dalam waktu lama. Ini...",options:["Tidak perlu diperhatikan, karena rasa kosong akan hilang sendiri tanpa bicara dengan orang lain, seberapa lama pun hal itu berlangsung","Bisa jadi cara tubuh melindungi diri dari sesuatu yang berat, & kalau berlangsung lama & mengganggu, layak dibicarakan dengan orang dewasa tepercaya","Berarti orang itu tidak peduli pada hal apa pun, sehingga sebaiknya orang lain menjauhinya dan tidak menanyakan keadaannya"],answer:1,explain:"Perasaan kosong atau mati rasa yang berkepanjangan adalah sinyal yang layak diperhatikan & dibicarakan, bukan diabaikan atau dianggap 'baik-baik saja'.",hint:"Sinyal yang layak dibicarakan, atau berarti tidak peduli / tak perlu diperhatikan?"},
{n:66,type:"mcq",micro:"Membedakan sedih biasa & yang lebih dalam",q:"Kesedihan sesekali (setelah hal mengecewakan) berbeda dari kesedihan yang...",options:["Hilang setelah beberapa jam atau hari, ketika kita sudah melakukan hal lain yang menyenangkan dan lupa pada masalahnya, tanpa mengganggu kegiatan sehari-hari kita","Terjadi karena alasan yang jelas & bisa dipahami, dan hilang begitu masalahnya selesai atau mendapat jalan keluar yang baik, sehingga tidak perlu dikhawatirkan sama sekali","Berlangsung lama, terus-menerus, disertai hilangnya minat pada hal yang biasanya disukai, & mengganggu fungsi sehari-hari, yang layak mendapat dukungan lebih"],answer:2,explain:"Semua orang sedih kadang-kadang. Yang perlu perhatian lebih adalah kesedihan yang dalam, menetap, & mengubah kemampuan menjalani hidup, itu tanda untuk mencari bantuan.",hint:"Yang menetap & mengganggu fungsi, atau yang hilang dalam beberapa hari?"},
{n:67,type:"mcq",micro:"Emosi & tidak menyalahkan diri",q:"Kalau kamu merasakan emosi yang menurut sebagian orang 'tidak seharusnya' (mis. sedih saat orang lain bilang 'seharusnya kamu senang'), sikap yang sehat:",options:["Perasaanmu sah bagimu; kamu tidak perlu membenarkannya pada semua orang, & bisa mencari orang yang mau mendengar tanpa menghakimi","Memaksa diri merasakan emosi yang 'seharusnya' menurut orang lain, & berhenti memercayai perasaanmu sendiri sama sekali","Menyimpulkan bahwa ada yang salah denganmu, lalu menyembunyikan perasaan itu dari semua orang supaya tidak dihakimi lagi"],answer:0,explain:"Emosi tidak selalu logis atau sesuai harapan orang lain, & itu tidak berarti salah. Kamu berhak atas perasaanmu sendiri.",hint:"Perasaanmu sah bagimu, atau harus sesuai harapan orang lain?"},
{n:68,type:"tf",micro:"Mengenali emosi membantu hubungan",q:"Benar atau Salah: Orang yang lebih mampu mengenali & menamai emosinya sendiri biasanya juga lebih mampu mengomunikasikan perasaan ke orang lain & memahami perasaan orang lain.",answer:true,explain:"Kesadaran emosi diri adalah fondasi dari komunikasi emosional yang baik & empati, keduanya penting untuk hubungan yang sehat.",hint:"Membantu komunikasi & empati, atau tak berhubungan dengan hubungan?"},
{n:69,type:"mcq",micro:"Emosi bukan alasan menyakiti orang",q:"Mengenali & mengakui emosi (mis. 'aku sangat marah') TIDAK berarti...",options:["Emosi membenarkan semua perilaku, jadi kalau sedang marah kita boleh melakukan apa saja tanpa harus bertanggung jawab","Boleh menyakiti orang lain atau merusak barang karena 'aku sedang marah'; perasaan diakui, tapi tindakan tetap tanggung jawab kita","Kita tidak bertanggung jawab atas apa yang kita lakukan saat marah, karena saat itu perasaanlah yang sedang mengendalikan kita"],answer:1,explain:"'Aku merasa marah' sah untuk diakui. 'Karena marah, aku boleh memukul' tidak sah. Mengenali emosi & memilih tindakan yang bertanggung jawab berjalan bersama.",hint:"Perasaan diakui tapi tindakan tetap tanggung jawab kita, atau emosi membenarkan semua perilaku?"},
{n:70,type:"tf",micro:"Kesadaran emosi berkembang seumur hidup",q:"Benar atau Salah: Kemampuan mengenali & memahami emosi terus berkembang sepanjang hidup, orang dewasa pun masih belajar lebih memahami perasaan mereka.",answer:true,explain:"Ini bukan keterampilan yang 'selesai' dipelajari. Sepanjang hidup ada pengalaman & emosi baru untuk dipahami.",hint:"Berkembang seumur hidup, atau selesai di usia tertentu?"},
{n:71,type:"mcq",micro:"Emosi & rasa syukur",q:"Sengaja memperhatikan hal-hal yang membuat kita merasa bersyukur/senang (sekecil apa pun) bisa membantu karena...",options:["Berarti kita mengabaikan perasaan sulit, sehingga masalah yang sebenarnya ada akan terus menumpuk tanpa pernah kita sadari","Membuat kita jadi tidak realistis & menutup mata dari kenyataan, karena hanya melihat hal-hal yang baik saja di sekitar kita","Melatih perhatian untuk juga menangkap emosi positif, bukan hanya yang negatif, yang sering lebih menonjol secara alami"],answer:2,explain:"Otak cenderung lebih memperhatikan hal negatif (untuk bertahan hidup). Sengaja memperhatikan yang positif menyeimbangkan gambaran emosi kita.",hint:"Melatih menangkap emosi positif, atau mengabaikan yang sulit / jadi tak realistis?"},
{n:72,type:"mcq",micro:"Menghormati emosi orang lain yang berbeda",q:"Kalau seseorang bereaksi emosional terhadap sesuatu yang menurutmu 'biasa saja', sikap yang menghormati:",options:["Menerima bahwa sesuatu yang kecil bagimu bisa besar bagi mereka, karena pengalaman & konteks tiap orang berbeda","Menganggap mereka pasti berlebihan & tidak masuk akal, karena hal sekecil itu seharusnya tidak membuat siapa pun bereaksi","Menyuruh mereka 'tidak usah baper' supaya cepat tenang, tanpa perlu mendengarkan apa yang sebenarnya mereka rasakan"],answer:0,explain:"Kita tidak selalu tahu apa yang sedang ditanggung orang lain atau apa arti sesuatu bagi mereka. Menerima perbedaan reaksi adalah bentuk penghormatan.",hint:"Menerima bahwa artinya berbeda bagi tiap orang, atau menganggap berlebihan / menyuruh 'tidak baper'?"},
{n:73,type:"mcq",micro:"Emosi & keputusan besar",q:"Untuk keputusan besar (pindah sekolah, mengakhiri pertemanan), peran emosi yang sehat:",options:["Keputusan besar harus dibuat persis saat emosi sedang paling kuat, karena pada saat itulah perasaan kita paling jujur, sehingga tidak perlu menunggu atau menimbang lagi","Emosi memberi informasi penting (apa yang terasa benar/salah), tapi dipertimbangkan bersama fakta & waktu, bukan diputuskan hanya saat emosi memuncak","Emosi harus diabaikan sepenuhnya dalam keputusan besar, karena hanya fakta & logika yang boleh menentukan pilihan kita, tanpa mempertimbangkan perasaan sedikit pun"],answer:1,explain:"Emosi & pikiran keduanya berharga dalam keputusan. Yang terbaik adalah mendengarkan keduanya, dengan waktu untuk menenang & merenung.",hint:"Emosi jadi informasi yang dipertimbangkan bersama fakta & waktu, atau diabaikan / diputuskan saat emosi puncak?"},
{n:74,type:"mcq",micro:"Emosi yang berulang & pesan yang belum didengar",q:"Kalau sebuah emosi terus muncul kembali meski situasinya berbeda-beda, itu bisa berarti...",options:["Emosi itu tidak ada artinya sama sekali, hanya kebetulan yang muncul berulang tanpa ada hubungan dengan hal apa pun","Kita harus mengabaikannya lebih keras lagi, sampai emosi itu menyerah dan berhenti muncul kembali dalam hidup kita","Ada sesuatu yang belum kita pahami atau tangani; emosi 'kembali' seperti mengetuk pintu sampai didengar"],answer:2,explain:"Emosi yang berulang sering jadi undangan untuk melihat lebih dalam, mungkin dengan bantuan orang tepercaya, apa kebutuhan atau luka yang belum terpenuhi.",hint:"Undangan untuk melihat lebih dalam, atau tak berarti / harus lebih diabaikan?"},
{n:75,type:"order",micro:"Menilai apakah emosi butuh perhatian lebih",q:"Urutkan langkah menilai apakah perasaan yang kamu alami butuh dukungan lebih dari sekadar cek diri sendiri.",items:["Perhatikan berapa lama perasaan itu berlangsung (beberapa jam? berhari-hari? berminggu-minggu?)","Perhatikan apakah itu mengganggu tidur, makan, sekolah, atau hubunganmu","Perhatikan apakah kamu masih bisa menikmati hal-hal yang biasanya kamu suka","Bila perasaan itu berat, lama, & mengganggu banyak hal, bicarakan dengan orang dewasa tepercaya"],answer:[0,1,2,3],explain:"Perhatikan durasi → dampak pada fungsi → hilangnya kesenangan → bicara ke dewasa bila berat & lama. Menilai bertahap, bukan panik pada emosi sesaat.",hint:"Berbicara ke orang dewasa dilakukan di awal atau setelah menilai durasi & dampaknya?"},
{n:76,type:"tf",micro:"Mengenali emosi bukan berkubang di dalamnya",q:"Benar atau Salah: Mengenali & mengakui emosi berbeda dari 'berkubang' (terus-menerus memikirkan & memperbesar perasaan tanpa henti); yang pertama sehat, yang kedua bisa memperberat.",answer:true,explain:"Mengenali: 'aku sedang sedih, itu tidak apa-apa'. Berkubang: memutar kejadian buruk berulang-ulang selama berjam-jam. Keseimbangan penting.",hint:"Mengakui itu sehat, berkubang bisa memberatkan, atau keduanya sama?"},
{n:77,type:"mcq",micro:"Emosi & merawat diri",q:"Setelah mengenali emosi yang sulit, langkah merawat diri yang wajar:",options:["Lakukan sesuatu yang menenangkan atau memberi energi (istirahat, bergerak, bicara dengan teman, melakukan hobi), sesuai kebutuhan saat itu","Menghukum diri karena merasakannya, dengan cara memarahi & mengkritik diri sendiri sampai perasaan yang sulit itu hilang","Memaksa diri terus produktif tanpa istirahat sedikit pun, supaya tidak ada waktu untuk memikirkan perasaan yang sulit itu"],answer:0,explain:"Mengenali emosi idealnya menuntun pada perawatan diri yang tepat, bukan pada penghukuman atau pengabaian kebutuhan.",hint:"Merawat diri sesuai kebutuhan, atau menghukum diri / abaikan kebutuhan?"},
{n:78,type:"mcq",micro:"Membantu teman mengenali emosinya",q:"Kalau temanmu bilang 'aku nggak tahu kenapa, aku cuma ngerasa nggak enak', cara membantu:",options:["Bilang 'ah nggak apa-apa itu' lalu mengganti topik pembicaraan supaya suasana tidak jadi canggung & berat bagi kalian","Dengarkan, & bantu dengan pertanyaan lembut ('kira-kira sejak kapan? ada yang terjadi belakangan ini?'), tanpa memaksakan kesimpulanmu","Langsung memberi tahu dia apa yang 'pasti' dia rasakan, karena kamu merasa sudah tahu persis apa masalahnya sejak awal"],answer:1,explain:"Membantu teman menamai perasaannya sendiri (dengan pertanyaan, bukan diagnosis) lebih memberdayakan daripada memberi tahu atau meremehkan.",hint:"Dengarkan & bantu dengan pertanyaan lembut, atau mendikte / meremehkan?"},
{n:79,type:"mcq",micro:"Emosi sebagai bagian dari diri utuh",q:"Cara pandang yang sehat: emosi adalah...",options:["Musuh yang harus dikendalikan sepenuhnya setiap saat, karena perasaan yang dibiarkan hanya akan merusak hidup kita","Hal yang membuat seseorang tidak bisa dipercaya, sehingga orang yang baik sebaiknya tidak pernah menunjukkan perasaannya","Bagian alami & berharga dari diri kita, sumber informasi & motivasi, bukan gangguan yang harus dikalahkan"],answer:2,explain:"Hubungan yang sehat dengan emosi adalah hubungan kerja sama, mendengarkan & bekerja dengannya, bukan perang melawannya.",hint:"Bagian berharga dari diri, atau musuh yang harus dikalahkan?"},
{n:80,type:"open",micro:"Membedakan emosi biasa & yang butuh dukungan lebih",q:"Jelaskan dengan kata-katamu sendiri: (a) apa perbedaan antara 'emosi sulit yang wajar & akan mereda' dengan 'emosi yang berat & mungkin butuh dukungan lebih (orang dewasa/profesional)', sebutkan minimal 3 pembeda, (b) kenapa penting tidak menghakimi diri sendiri atau orang lain saat butuh dukungan lebih, (c) contoh kalimat yang bisa dipakai untuk memulai percakapan meminta bantuan ke orang dewasa tepercaya.",explain:"Jawaban baik: minimal 3 pembeda yang jelas & benar (durasi, dampak pada fungsi dasar, hilangnya kesenangan, kemampuan mengelola sendiri), penjelasan yang menekankan bahwa mencari bantuan adalah keberanian bukan kelemahan (analogi dengan sakit fisik membantu), & contoh kalimat pembuka percakapan yang konkret, jujur, & bisa benar-benar diucapkan.",hint:"Pembeda utamanya: berapa LAMA, seberapa mengganggu HAL-HAL DASAR (tidur/makan/sekolah), & apakah masih bisa MENIKMATI hal yang biasa disukai.",sample:"(a) Perbedaan: (1) DURASI, emosi sulit yang wajar biasanya mereda dalam beberapa jam atau hari; yang butuh dukungan lebih berlangsung berminggu-minggu atau lebih tanpa membaik. (2) DAMPAK PADA FUNGSI, emosi wajar mungkin mengganggu sebentar tapi kita masih bisa tidur, makan, & mengikuti sekolah; yang lebih berat mengganggu hal-hal dasar itu secara terus-menerus. (3) HILANGNYA KESENANGAN, dalam emosi wajar kita masih bisa menikmati hal yang biasa kita suka meski sedang sedih; yang lebih berat membuat hampir semua hal terasa hambar atau tidak menarik. (4) KEMAMPUAN MENGELOLA SENDIRI, emosi wajar biasanya bisa kita hadapi dengan cek diri, bicara dengan teman, atau merawat diri; yang lebih berat terasa di luar kemampuan kita untuk ditangani sendiri meski sudah mencoba. (b) Kenapa tidak menghakimi: karena butuh dukungan lebih bukan tanda kelemahan atau kegagalan, sama seperti tubuh yang sakit butuh dokter, perasaan yang berat & lama juga layak mendapat bantuan yang tepat; menghakimi (diri sendiri atau orang lain) hanya menambah beban & membuat orang malu untuk mencari bantuan padahal itu langkah yang berani & bijak. (c) Contoh kalimat memulai percakapan: 'Bu/Pak, aku ingin cerita sesuatu. Belakangan ini aku sering merasa sangat sedih/cemas dan rasanya tidak hilang-hilang, sampai aku jadi susah tidur dan susah fokus di sekolah. Aku sudah coba mengatasinya sendiri tapi masih berat. Boleh aku minta bantuan untuk memikirkan apa yang bisa kulakukan?'"},
{n:81,type:"mcq",micro:"Skenario: emosi campur aduk saat perpisahan",q:"Sahabatmu akan pindah ke kota lain. Kamu merasa sedih, tapi juga senang untuknya, & sedikit cemas soal pertemanan kalian. Cara menyikapi emosi campur aduk ini:",options:["Akui bahwa semua perasaan itu ada bersamaan & wajar; kamu tidak harus 'memilih' satu perasaan saja","Paksa diri hanya merasa senang untuknya & menekan perasaan yang lain, supaya kamu terlihat seperti sahabat yang baik","Simpulkan bahwa kamu bukan sahabat yang baik karena merasa sedih, lalu menjauh darinya supaya dia tidak ikut sedih"],answer:0,explain:"Emosi campuran dalam situasi kompleks adalah hal yang normal & bahkan menunjukkan kedalaman perasaanmu, bukan sesuatu yang salah.",hint:"Akui semua perasaan bersamaan, atau paksa satu / menghakimi diri?"},
{n:82,type:"mcq",micro:"Skenario: tidak bisa menamai perasaan",q:"Kamu merasa 'berat' seharian tapi tidak tahu kenapa & tidak bisa menamainya. Langkah yang membantu:",options:["Mengabaikan dan berpura-pura tidak ada apa-apa, karena perasaan yang tidak bernama tidak penting diperhatikan, apalagi sampai dibicarakan dengan orang lain","Cek hal-hal dasar (cukup tidur? makan? ada yang menumpuk?), tulis beberapa kalimat bebas tentang harimu, & beri diri ruang, kadang kejelasan datang perlahan","Memaksa diri menemukan nama yang tepat dalam 5 menit, dan terus menekan diri sampai ketemu jawaban, walau kamu sudah kelelahan"],answer:1,explain:"Tidak semua perasaan langsung punya nama yang jelas. Memeriksa kondisi fisik & menulis bebas bisa membantu kejelasan muncul secara alami.",hint:"Cek kondisi dasar + tulis bebas + beri ruang, atau paksa cari nama / abaikan?"},
{n:83,type:"mcq",micro:"Skenario: emosi kuat sebelum pertandingan",q:"Sebelum pertandingan penting, kamu merasa jantung berdebar & perut mual, & berpikir 'aku pasti kalah'. Cara mengenali & menyikapi:",options:["Simpulkan bahwa perasaan itu adalah ramalan pasti kekalahan, jadi sebaiknya tidak usah berusaha sungguh-sungguh lagi nanti","Batalkan ikut pertandingan karena merasa gugup, sebab perasaan gugup berarti kamu memang belum siap untuk bertanding","Kenali: 'ini gugup, tubuhku bersiap untuk sesuatu yang penting'; gugup bisa jadi energi, bukan hanya ancaman"],answer:2,explain:"Sensasi gugup (jantung berdebar, perut mual) sering mirip dengan sensasi bersemangat. Menamainya sebagai 'siap & bersemangat' bisa mengubah pengalamannya.",hint:"Kenali gugup sebagai persiapan/energi, atau anggap ramalan kekalahan / batalkan?"},
{n:84,type:"mcq",micro:"Skenario: teman meremehkan perasaanmu",q:"Kamu bercerita bahwa kamu sedih soal sesuatu, & temanmu bilang 'ah gitu doang, lebay'. Sikap yang menjaga dirimu:",options:["Ingat bahwa perasaanmu tetap sah meski orang lain tidak memahaminya; cari orang lain yang mau mendengar dengan lebih baik","Percaya bahwa kamu memang lebay & perasaanmu tidak valid, lalu belajar menyembunyikannya supaya tidak ditertawakan lagi","Berhenti bercerita ke siapa pun selamanya, karena tidak ada seorang pun yang akan benar-benar mau mendengarkan perasaanmu"],answer:0,explain:"Reaksi orang lain yang meremehkan tidak membuat perasaanmu jadi tidak nyata. Mencari pendengar yang lebih empati adalah langkah yang sehat.",hint:"Perasaanmu tetap sah & cari pendengar lain, atau percaya kamu lebay / berhenti bercerita?"},
{n:85,type:"tf",micro:"Kesadaran emosi adalah keterampilan hidup",q:"Benar atau Salah: Kemampuan mengenali & memahami emosi diri sendiri adalah keterampilan hidup penting yang membantu dalam belajar, hubungan, pengambilan keputusan, & kesejahteraan secara keseluruhan.",answer:true,explain:"Kesadaran emosi adalah fondasi dari kecerdasan emosi, yang berperan besar dalam hampir semua aspek kehidupan.",hint:"Keterampilan hidup penting yang luas manfaatnya, atau hanya soal 'baper'?"},
{n:86,type:"mcq",micro:"Skenario: emosi yang muncul saat mengingat masa lalu",q:"Sebuah lagu memicu kenangan yang membuatmu tiba-tiba sangat sedih di tengah hari biasa. Cara menyikapi:",options:["Berusaha keras tidak pernah mendengar lagu apa pun lagi, supaya kenangan sedih itu tidak akan pernah muncul kembali","Akui: 'lagu ini membawa kembali perasaan lama'; beri diri ruang sejenak, & tahu bahwa gelombang ini akan mereda","Marah pada diri sendiri karena 'masih memikirkan itu', lalu memaksa diri berhenti merasa sedih secepat mungkin hari itu"],answer:1,explain:"Emosi yang dipicu kenangan adalah hal manusiawi. Mengenali sumbernya & mengizinkan diri merasakannya sejenak lebih sehat daripada marah pada diri.",hint:"Akui sumbernya & beri ruang, atau marah pada diri / hindari semua lagu?"},
{n:87,type:"mcq",micro:"Skenario: membantu adik yang tidak bisa mengungkapkan perasaan",q:"Adikmu yang lebih kecil sedang jelas kesal tapi hanya bisa bilang 'aku benci semuanya'. Cara membantu:",options:["Bilang 'jangan bilang benci' & menyuruhnya diam, supaya dia belajar tidak mengucapkan kata-kata yang tidak baik lagi","Mengabaikannya karena 'nanti juga reda sendiri', sehingga kamu tidak perlu repot menanyakan apa yang sebenarnya terjadi padanya","Bantu dia menamai dengan lembut ('kamu kelihatan kesal banget, ada yang bikin kamu marah tadi?') & dengarkan"],answer:2,explain:"Anak yang lebih kecil sering belum punya kata untuk perasaannya. Membantu menamai dengan sabar mengajarkan keterampilan penting.",hint:"Bantu namai dengan lembut & dengarkan, atau larang / abaikan?"},
{n:88,type:"mcq",micro:"Skenario: emosi yang bertentangan dengan 'seharusnya'",q:"Kamu diterima di kegiatan yang kamu impikan, tapi malah merasa cemas & ragu, bukan gembira seperti 'seharusnya'. Cara menyikapi:",options:["Akui perasaan yang sebenarnya ada tanpa menghakiminya; cemas menghadapi hal baru yang penting adalah wajar, & tidak menghapus bahwa kamu menginginkannya","Paksa diri merasa gembira & menekan kecemasan, karena orang yang diterima seharusnya hanya merasa senang dan bangga, apa pun yang sebenarnya kamu rasakan saat itu","Simpulkan bahwa kamu sebenarnya tidak menginginkannya, karena kalau mau kamu tak akan cemas, lalu mundur dari kegiatan itu"],answer:0,explain:"Perasaan tidak selalu 'sesuai skenario'. Cemas menghadapi tantangan baru yang berarti adalah bagian normal, bukan tanda kamu salah menginginkannya.",hint:"Akui perasaan sebenarnya tanpa menghakimi, atau paksa gembira / simpulkan tak mau?"},
{n:89,type:"mcq",micro:"Skenario: menyeimbangkan mengenali emosi & menjalani hidup",q:"Kamu jadi sangat sadar pada setiap perasaan kecil sampai merasa kewalahan menganalisis terus. Sikap yang seimbang:",options:["Menghabiskan seluruh hari menganalisis setiap perasaan sekecil apa saja, supaya tidak ada emosi yang terlewat dipahami","Cek diri secukupnya (mis. 1-2 kali sehari), lalu izinkan diri menjalani hidup tanpa harus menganalisis setiap emosi sepanjang waktu","Berhenti memperhatikan emosi mulai sekarang, supaya tidak ada perasaan yang membuatmu kewalahan menganalisisnya"],answer:1,explain:"Kesadaran emosi yang sehat adalah alat, bukan pekerjaan penuh waktu. Cek diri secukupnya lalu hidup, bukan terus-menerus mengawasi diri.",hint:"Cek diri secukupnya lalu jalani hidup, atau berhenti total / analisis tanpa henti?"},
{n:90,type:"order",micro:"Proyek: 'kamus emosi' pribadi selama sebulan",q:"Urutkan langkah membuat 'kamus emosi' pribadi selama sebulan.",items:["Setiap kali merasakan emosi yang cukup jelas, catat: nama emosi, pemicu, sensasi tubuh, intensitas","Setelah 1-2 minggu, kelompokkan catatan untuk melihat emosi apa yang paling sering & pemicu apa yang berulang","Untuk emosi yang sering muncul, tulis 'apa yang biasanya membantu' saat merasakannya","Di akhir bulan, buat ringkasan: pemahaman baru tentang dirimu & pola emosimu"],answer:[0,1,2,3],explain:"Catat konsisten → cari pola → catat yang membantu → ringkas pemahaman. Data dari pengalaman sendiri jadi 'kamus' yang personal & berguna.",hint:"Mencari pola dari catatan dilakukan sebelum atau sesudah mengumpulkan catatan selama 1-2 minggu?"},
{n:91,type:"mcq",micro:"Skenario: emosi kuat di depan orang banyak",q:"Kamu tiba-tiba merasa akan menangis di kelas karena sesuatu. Cara menyikapi saat itu:",options:["Marah pada diri karena 'lemah' & memaksa diri berhenti menangis saat itu juga, karena menangis di kelas itu memalukan dan tidak boleh dilakukan","Menahan sekuat tenaga sampai dada sakit & tidak mengizinkan diri merasa, supaya tak ada yang tahu perasaanmu","Akui pada diri sendiri ('aku sedang sangat terharu/sedih'), tarik napas beberapa kali, & bila perlu minta izin ke luar sebentar; menangis pun tidak apa-apa"],answer:2,explain:"Emosi kuat bisa muncul di waktu yang tidak nyaman. Mengakuinya, menenangkan diri sebentar, & mengizinkan diri (termasuk menangis atau keluar sebentar) adalah respons yang sehat & manusiawi.",hint:"Akui + napas + minta izin bila perlu, atau marah pada diri / tahan mati-matian?"},
{n:92,type:"tf",micro:"Semua emosi layak dikenali",q:"Benar atau Salah: Tidak ada emosi yang 'tidak boleh' dikenali atau diakui pada diri sendiri, meski beberapa (iri, benci, malu) terasa tidak nyaman untuk diakui.",answer:true,explain:"Mengakui emosi yang tidak nyaman pada diri sendiri (bukan berarti bertindak berdasarkannya) adalah langkah pertama memahami & menanganinya dengan sehat.",hint:"Semua layak dikenali pada diri sendiri, atau beberapa harus disangkal?"},
{n:93,type:"mcq",micro:"Skenario: membantu teman yang menyangkal perasaannya",q:"Temanmu jelas terluka soal sesuatu tapi terus bilang 'aku nggak apa-apa kok' sambil terlihat murung. Sikap yang menghormati:",options:["Sampaikan bahwa kamu ada untuknya kapan pun ia siap bercerita, tanpa memaksa; hormati bahwa ia mungkin belum siap","Memaksanya mengakui perasaannya sekarang juga, & terus bertanya sampai dia mau menceritakan semuanya kepadamu hari ini","Percaya sepenuhnya bahwa dia 'nggak apa-apa' & tidak peduli lagi, karena dia sendiri yang bilang begitu kepadamu tadi"],answer:0,explain:"Kita tidak bisa memaksa orang mengenali atau membagikan perasaannya. Menawarkan kehadiran tanpa memaksa menghormati kesiapan mereka.",hint:"Tawarkan kehadiran tanpa memaksa, atau paksa mengakui / abai sepenuhnya?"},
{n:94,type:"mcq",micro:"Skenario: emosi setelah membantu orang lain",q:"Setelah mendengarkan masalah berat temanmu, kamu sendiri jadi merasa lelah & sedih. Cara menyikapi:",options:["Berhenti peduli pada teman selamanya agar tidak lelah, & tidak mau mendengarkan masalah siapa pun lagi mulai sekarang, apa pun alasan dan keadaannya","Akui bahwa peduli pada orang lain butuh energi; rawat dirimu setelahnya (istirahat, lakukan hal yang mengisi energimu) & tidak apa-apa punya batas","Menyimpulkan bahwa kamu egois karena lelah, lalu memaksa diri tetap mendengarkan terus tanpa istirahat sedikit pun lagi, sampai kamu benar-benar tidak sanggup"],answer:1,explain:"Empati punya biaya emosional. Merawat diri setelah mendukung orang lain (& tahu batas) membuat kita bisa terus peduli dalam jangka panjang.",hint:"Rawat diri & tahu batas, atau menyimpulkan egois / berhenti peduli total?"},
{n:95,type:"tf",micro:"Mengenali emosi mendukung kesejahteraan",q:"Benar atau Salah: Orang yang terbiasa mengenali & memahami emosinya cenderung lebih mampu merawat diri, meminta bantuan saat perlu, & menjaga kesejahteraannya dari waktu ke waktu.",answer:true,explain:"Kesadaran emosi adalah fondasi merawat diri, kita tidak bisa merawat sesuatu yang tidak kita sadari.",hint:"Mendukung kemampuan merawat diri, atau tak berpengaruh pada kesejahteraan?"},
{n:96,type:"mcq",micro:"Skenario: menjadi teladan kesadaran emosi",q:"Adik/sepupu yang lebih muda mengamati bagaimana kamu menangani emosi. Cara menjadi teladan yang baik:",options:["Selalu berpura-pura tidak pernah merasakan emosi apa pun di depan mereka, supaya mereka mengira orang dewasa tidak pernah kesal","Meledak tanpa kendali lalu menyuruh mereka 'jangan seperti aku', tanpa pernah menjelaskan apa yang sebenarnya sedang kamu rasakan","Sesekali menamai emosimu dengan terbuka ('aku lagi kesal nih, aku mau tenang dulu sebentar') & menunjukkan cara sehat menanganinya"],answer:2,explain:"Anak belajar mengenali & mengelola emosi dari melihat orang di sekitarnya melakukannya secara sehat & terbuka, bukan dari sikap yang menyembunyikan atau meledak.",hint:"Namai emosi terbuka & tunjukkan cara sehat, atau berpura-pura tak beremosi / meledak?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup terampil mengenali emosi:",options:["Kamu bisa menamai perasaanmu dengan cukup spesifik, menyadari sensasi tubuh yang menyertai, mengenali pemicu & pola, & tahu kapan butuh dukungan lebih","Kamu hafal daftar nama emosi dengan lengkap tapi jarang memeriksa perasaanmu sendiri atau memperhatikan sensasi di tubuhmu saat itu","Kamu berhenti merasakan emosi sehingga tidak ada perasaan yang mengganggu, & kamu merasa tak butuh dukungan"],answer:0,explain:"Keterampilan sejati terlihat dari kemampuan menamai, menyadari tubuh, mengenali pola, & tahu batas, bukan hafalan atau 'mati rasa'.",hint:"Bisa menamai + sadar tubuh + kenali pola + tahu batas, atau hafal daftar / mati rasa?"},
{n:98,type:"mcq",micro:"Emosi & masyarakat",q:"Lingkungan (keluarga, kelas, komunitas) di mana orang merasa aman mengakui & membicarakan perasaan cenderung...",options:["Tidak berbeda dari lingkungan yang melarang membicarakan perasaan, karena setiap orang menghadapi emosinya sendiri","Lebih mendukung kesejahteraan semua anggotanya & lebih cepat membantu yang sedang kesulitan","Menjadi tempat yang lemah dan tidak produktif, karena waktu terbuang untuk membicarakan perasaan"],answer:1,explain:"Rasa aman untuk jujur soal perasaan membangun lingkungan yang lebih peduli & tangguh secara kolektif.",hint:"Lebih mendukung kesejahteraan, atau lemah / tak berbeda?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'mengenali emosi':",options:["Berusaha keras tidak merasakan emosi supaya hidup lebih tenang dan tak ada perasaan yang mengganggu keputusan penting, dan menganggap semua emosi sebagai gangguan yang tidak berguna","Menganalisis setiap perasaan tanpa henti sepanjang hari, mencari penyebab dan nama yang paling tepat sampai tidak ada waktu untuk hal lain, termasuk belajar dan bermain","Berhenti sejenak untuk memperhatikan apa yang kamu rasakan, memberinya nama yang lebih tepat, menyadari sensasi tubuh & pemicunya, tanpa menghakimi diri, & tahu kapan perasaan butuh dukungan lebih"],answer:2,explain:"Perhatikan + namai + sadari tubuh & pemicu + tanpa menghakimi + tahu kapan butuh bantuan. Ini fondasi hubungan yang sehat dengan kehidupan emosi kita.",hint:"Perhatikan + namai + tanpa menghakimi + tahu batas, atau tak merasa / analisis tanpa henti?"},
{n:100,type:"open",micro:"Kapstone: hubungan sehat dengan emosi",q:"Tulis rencana pribadi untuk membangun hubungan yang lebih sehat dengan emosimu. Sertakan: (a) satu kebiasaan cek diri yang akan kamu terapkan, (b) bagaimana kamu akan merespons saat menyadari emosi yang sulit (langkah-langkah), (c) daftar 2-3 orang tepercaya yang bisa kamu ajak bicara & kapan, (d) tanda-tanda yang akan membuatmu tahu bahwa sebuah perasaan butuh dukungan lebih dari sekadar cek diri sendiri, (e) satu hal baik yang kamu harap tumbuh dari kebiasaan ini.",explain:"Jawaban baik: kebiasaan cek diri yang spesifik & realistis, langkah respons yang berurutan & mencakup mengakui + menenangkan tubuh + menilai + memenuhi kebutuhan, daftar orang tepercaya yang spesifik dengan konteks kapan, tanda-tanda butuh dukungan lebih yang konkret (durasi, dampak fungsi, hilangnya minat) dengan rencana bicara ke siapa, & harapan pertumbuhan yang bermakna & personal.",hint:"Bagian (d) yang paling penting untuk topik sensitif ini, buat tanda-tandanya konkret & sertakan rencana konkret bicara ke siapa, bukan hanya 'akan cari bantuan'.",sample:"(a) Kebiasaan cek diri: setiap malam sebelum tidur, aku akan meluangkan 3 menit menulis di buku catatan, satu kata emosi utama hari itu, apa pemicunya, & di mana aku merasakannya di tubuh. (b) Respons saat menyadari emosi sulit: (1) Berhenti & akui, 'aku sedang merasa ___, itu tidak apa-apa.' (2) Tarik napas perlahan beberapa kali & perhatikan tubuhku. (3) Tanya, 'seberapa kuat ini (1-10) & apa yang mungkin memicunya?' (4) Tanya, 'apa yang aku butuhkan sekarang?', mungkin istirahat, bergerak, atau bicara dengan seseorang, lalu lakukan hal itu. (5) Ingat bahwa emosi ini seperti gelombang & akan mereda. (c) Orang tepercaya: ibuku (untuk hal-hal yang menyangkut keluarga atau perasaan yang berat, kapan saja aku merasa perlu), sahabatku Dina (untuk cerita sehari-hari & perasaan biasa, biasanya saat kami mengobrol sepulang sekolah), & wali kelasku (untuk hal yang menyangkut sekolah atau kalau aku merasa butuh orang dewasa selain keluarga). (d) Tanda butuh dukungan lebih: kalau sebuah perasaan berat berlangsung lebih dari dua minggu tanpa membaik, kalau aku jadi susah tidur atau makan terus-menerus, kalau aku kehilangan minat pada hampir semua hal yang biasanya kusuka, atau kalau aku merasa perasaan ini benar-benar di luar kemampuanku untuk ditangani sendiri meski sudah mencoba, maka aku akan bicara dengan ibuku atau wali kelas & terbuka bahwa aku mungkin butuh bantuan lebih (misalnya konselor). (e) Hal baik yang kuharap tumbuh: aku berharap jadi lebih tenang menghadapi hari-hari sulit karena aku tahu perasaan datang & pergi, lebih bisa mengomunikasikan apa yang kurasakan & kubutuhkan ke orang lain, & lebih peka juga pada perasaan orang di sekitarku."},
];
